      role1 = 2127000,
      role2 = 201105,
      role3 = 201205,
      role5 = 2127404,
      role6 = 21285005,
      sentence = "His tone was placid, and for some reason, I found myself nodding without hesitation. He seemed a bit surprised, and a bright smile rippled across his eyes.",
      next = {69}
    },
    [69] = {
      beijing = 4593,
      dialog = 2,
      idx = 2,
