      role1 = 2127000,
      role2 = 201105,
      role3 = 201201,
      role5 = 2127404,
      role6 = 21285005,
      sentence = "On this continent, everything looks incredibly lifelike. There are lush forests, sprawling grasslands, and vast deserts.",
      voice = 2,
      next = {76}
    },
    [76] = {
      beijing = 4593,
      dialog = 2,
