      renwu = "npc",
      role1 = 2127000,
      role2 = 201105,
      role3 = 201201,
      role5 = 2127404,
      role6 = 21285005,
      sentence = "But what left the deepest impression on me were those great flying fish you spoke of.",
      voice = 2,
