      renwu = "npc",
      role1 = 2127000,
      role2 = 201105,
      role3 = 201204,
      role5 = 2127404,
      role6 = 21285005,
      sentence = "Because they're obviously creatures of the sea, and yet they can break free from the sea and take to the sky.",
      next = {83}
    },
    [83] = {
      beijing = 4593,
      dialog = 2,
      idx = 2,
