      renming = "Lucien",
      renwu = "npc",
      role1 = 2127000,
      role2 = 201106,
      role3 = 201204,
      role5 = 2127404,
      role6 = 21285005,
      sentence = "But what if I told you that a kun-peng must maintain a certain body temperature over the long term...",
      voice = 2,
