      renwu = "npc",
      role1 = 2127000,
      role2 = 201106,
      role3 = 201204,
      role5 = 2127404,
      role6 = 21285005,
      sentence = "...and if they don't return to the ocean depths in time, then the high-altitude sunlight becomes imminently lethal to them?",
