      role1 = 2127000,
      role2 = 201105,
      role3 = 201204,
      role5 = 2127404,
      role6 = 21285005,
      sentence = "I was taken aback. I felt as if I'd been lured into opening a door I'd never tried to peer behind before, and I instinctively fumbled for a rebuttal.",
