      renwu = "npc",
      role1 = 2127000,
      role2 = 201106,
      role3 = 201204,
      role5 = 2127404,
      role6 = 21285005,
      sentence = "Rather than considering it a \"choice\", I am inclined to see it as their survival instinct, and as a constraint of nature.",
