      role1 = 2127000,
      role2 = 201105,
      role3 = 201204,
      role5 = 2127404,
      role6 = 21285005,
      sentence = "I didn't know why he was suddenly asking this, but as I thought about the freewheeling and independent crew, I gave a sincere nod.",
      next = {98}
    },
    [98] = {
