      role1 = 2127000,
      role2 = 201106,
      role3 = 201204,
      role5 = 2127404,
      role6 = 21285005,
      sentence = "If someone feels pained or perplexed by this, then perhaps what she must do is think of a way to steer this world in the direction of her yearning.",
