      role1 = 2127000,
      role2 = 201106,
      role3 = 201204,
      role5 = 2127404,
      role6 = 21285005,
      sentence = "He spoke slowly, as if he was leaving that much more unsaid. I felt an odd surge of frustration inside, and for the time I didn't know what to say.",
      next = {107}
    },
    [107] = {
