    },
    [111] = {
      beijing = 4593,
      dialog = 3,
      music = "204_Affectionate_Scene",
      renwu = "npc",
      sentence = "With that, he was about to walk away, when I suddenly found myself uttering these words:",
      next = {112}
    },
    [112] = {
